update gallery_exhibitions set intro = '오스트리아 빈의 벨베데레 미술관은 사보이의 오이겐 공이 18세기 초에 지은 바로크 여름 궁전을 그대로 미술관으로 사용하는, 건물 자체가 걸작인 공간입니다. 상궁(Oberes Belvedere)에는 구스타프 클림트의 「키스」를 비롯해 세계 최대의 클림트 유화 컬렉션이 소장되어 있으며, 에곤 실레와 오스카 코코슈카 등 빈 모더니즘의 정수를 만날 수 있습니다. 중세부터 현대까지 오스트리아 미술 800년의 흐름을 아우르는 국립 컬렉션으로, 정형식 정원 너머로 빈 시가지가 내려다보이는 전망 또한 유명합니다.' where name = 'Belvedere';
update gallery_exhibitions set intro = '1903년에 설립된 댈러스 미술관은 미국 남서부를 대표하는 종합 미술관으로, 고대부터 현대까지 5,000년에 걸친 약 25,000점의 컬렉션을 소장하고 있습니다. 유럽 인상주의와 미국 회화, 아프리카·아시아 미술, 장식미술에 이르는 폭넓은 소장품을 자랑하며, 일반 관람을 무료로 개방해 시민의 미술관이라는 정신을 실천하고 있습니다. 다운타운 예술지구의 중심에 자리하여 댈러스 문화의 심장 역할을 하고 있습니다.' where name = 'Dallas Museum of Art';
update gallery_exhibitions set intro = '로스앤젤레스 브렌트우드 언덕 위의 게티 센터는 석유 재벌 J. 폴 게티의 유산으로 세워진 미술관으로, 리처드 마이어가 설계한 백색 트래버틴 건축과 로버트 어윈의 중앙 정원만으로도 방문할 가치가 있는 곳입니다. 중세 필사본부터 19세기 유럽 회화까지 알찬 컬렉션을 갖추었으며, 1990년 경매 사상 최고가로 구입한 반 고흐의 「아이리스」와 렘브란트, 모네, 터너의 걸작들을 무료로 공개합니다. 언덕 위에서 태평양과 LA 시가지가 한눈에 들어오는 전망도 명물입니다.' where name = 'J. Paul Getty Museum';
update gallery_exhibitions set intro = '스위스 바젤 시립미술관은 1661년 바젤시가 아머바흐 가문의 컬렉션을 사들이며 출발한, 세계에서 가장 오래된 공공 미술 컬렉션입니다. 한스 홀바인 부자의 작품을 세계에서 가장 많이 소장하고 있으며, 1967년에는 피카소 작품 구입을 위해 시민투표로 예산을 승인해 감동한 피카소가 넉 점을 추가 기증한 일화로도 유명합니다. 르네상스부터 뵈클린, 호들러, 피카소, 몬드리안, 샤갈에 이르는 컬렉션은 유럽 미술사의 축소판이라 불립니다.' where name = 'kunstmuseumbasel';
update gallery_exhibitions set intro = '뮌헨의 렌바흐하우스는 초상화가 프란츠 폰 렌바흐의 이탈리아풍 저택을 개조한 시립미술관으로, 청기사파(Der Blaue Reiter) 컬렉션의 세계적 본산입니다. 1957년 칸딘스키의 동반자였던 화가 가브리엘레 뮌터가 나치 시대에 지켜낸 칸딘스키 초기작 등 1,000여 점을 기증하면서 순식간에 세계적 미술관의 반열에 올랐습니다. 칸딘스키, 프란츠 마르크, 아우구스트 마케, 파울 클레가 색채 혁명을 일으킨 현장을 이곳에서 확인할 수 있습니다.' where name = 'Lenbachhaus';
update gallery_exhibitions set intro = '1883년 시민들의 발의로 출발한 미니애폴리스 미술관(Mia)은 5,000년 세계 미술사를 아우르는 약 90,000점의 컬렉션을 소장한 미국 중서부의 대표 미술관입니다. 렘브란트, 반 고흐, 모네를 비롯한 유럽 거장과 방대한 아시아 미술 컬렉션으로 유명하며, 설립 이래 입장료 없이 모든 시민에게 무료로 개방한다는 원칙을 지켜오고 있습니다.' where name = 'MIA-Minneapolis Institute of Art';
update gallery_exhibitions set intro = '프랑스 샴페인의 수도이자 역대 프랑스 왕들의 대관식이 열린 랭스 대성당의 도시, 랭스의 보자르 미술관입니다. 바르비종파의 스승 카미유 코로의 작품을 루브르 다음으로 많이 소장한 것으로 유명하며, 부댕, 밀레, 모네, 피사로, 르누아르로 이어지는 프랑스 풍경화의 계보를 한자리에서 볼 수 있습니다. 크랜치의 독일 르네상스 초상과 자크루이 다비드의 「마라의 죽음」 이본 등 유럽 회화사의 보석들도 품고 있습니다.' where name = 'musees-reims';
update gallery_exhibitions set intro = '워싱턴 D.C. 내셔널 몰에 자리한 미국 국립미술관은 금융가 앤드루 멜런이 컬렉션과 건축비를 국가에 기증하며 1941년 문을 열었습니다. 미주 대륙에서 유일한 레오나르도 다빈치 유화 「지네브라 데 벤치」를 소장하고 있으며, 라파엘로부터 렘브란트, 인상주의, 미국 회화까지 서양 미술사 전체를 아우르는 15만 점의 컬렉션을 자랑합니다. 국립기관으로서 설립 이래 모든 전시를 무료로 개방하고 있습니다.' where name = 'National Gallery of Art';
update gallery_exhibitions set intro = '1879년에 설립된 크라쿠프 국립박물관은 폴란드 최초의 국립박물관으로, 분할 점령기 폴란드인의 문화적 정체성을 지켜온 정신적 보루였습니다. 레오나르도 다빈치의 「흰 담비를 안은 여인」 소장처로 세계적 명성을 얻었으며, 얀 마테이코의 역사화와 믈로다 폴스카(젊은 폴란드) 운동의 회화 등 폴란드 미술의 정수를 여러 분관에 걸쳐 소장하고 있습니다. 본 전시는 폴란드 풍경화와 사실주의 회화의 아름다움을 소개합니다.' where name = 'National Museum in Krakow';
update gallery_exhibitions set intro = '2022년 오슬로 항구에 개관한 노르웨이 국립미술관은 기존 국립미술관·건축박물관·장식미술관을 통합한 북유럽 최대 규모의 미술관입니다. 에드바르 뭉크의 1893년작 「절규」 원본이 이곳의 심장이며, 요한 크리스티안 달의 낭만주의 풍경화부터 하리에트 바케르의 실내화, 그리고 세잔과 피카소까지 노르웨이와 유럽 미술의 대화를 보여줍니다. 알루미늄 재질의 빛나는 전시홀 ''리스할렌''은 새로운 오슬로의 랜드마크가 되었습니다.' where name = 'National Museum, Norway';
update gallery_exhibitions set intro = '덴마크 코펜하겐 북쪽 해안 마을 니보에 자리한 니바고르 컬렉션은 실업가 요하네스 하게가 1908년 자신의 저택 곁에 세운 개인 미술관에서 출발했습니다. 에케르스베르, 룬뷔에, 쇠보 등 덴마크 황금기(1800-1850) 회화의 정수와 이탈리아 르네상스, 네덜란드 바로크 걸작을 소장하고 있으며, 봄이면 만개하는 진달래 정원으로도 사랑받는 아담하고 품격 있는 미술관입니다.' where name = 'Nivaagaard';
update gallery_exhibitions set intro = '미국 매사추세츠 윌리엄스타운의 클라크 미술관은 싱거 재봉틀 상속자 로버트 스털링 클라크 부부가 1955년 설립한 곳으로, 르누아르 30여 점을 비롯한 프랑스 인상주의 컬렉션의 밀도로 세계적 명성을 얻고 있습니다. 모네, 피사로, 드가와 미국 화가 윈슬로 호머, 사전트의 걸작을 소장하며, 안도 다다오가 설계한 증축관과 버크셔 산자락의 목가적 풍경이 어우러진 예술 안식처로 꼽힙니다. 미술사 연구소를 함께 운영하는 연구 중심 기관이기도 합니다.' where name = 'The clark';
update gallery_exhibitions set intro = '스톡홀름 유르고르덴 섬 끝자락의 틸스카 갤러리는 은행가 에른스트 틸이 세기말에 수집한 북유럽 미술을 그의 백색 저택과 함께 공개한 미술관입니다. 뭉크가 직접 틸에게 판매한 회화와 판화들, 칼 라르손, 브루노 릴리에포르스, 아우구스트 스트린드베리의 작품이 소장되어 있으며, 틸이 심취했던 철학자 니체의 데스마스크가 있는 것으로도 유명합니다. 발트해가 내려다보이는 갤러리 정원은 스톡홀름의 숨은 명소입니다.' where name = 'Thielska Galleriet';
update gallery_exhibitions set intro = '빈 박물관은 카를스플라츠에 자리한 빈 시립박물관으로, 로마 시대부터 현대까지 도시 빈의 역사와 예술을 총체적으로 보여주는 곳입니다. 클림트의 초기 걸작과 에곤 실레의 자화상, 비더마이어 시대의 풍속화, 그리고 오토 바그너의 건축 도면까지 소장하며, 세기말 빈의 화려한 문화를 도시의 일상사와 함께 읽어낼 수 있는 독특한 컬렉션을 자랑합니다. 본 전시는 빈의 풍경과 사람들을 그린 회화들을 중심으로 구성했습니다.' where name = 'wienmuseum';
update gallery_exhibitions set intro = '1832년 화가 존 트럼불의 독립전쟁 역사화 기증으로 출발한 예일대학교 미술관은 미국에서 가장 오래된 대학 미술관입니다. 반 고흐의 「밤의 카페」, 조지 스터브스의 말 그림, 그리고 미국 초기 회화의 최대 컬렉션을 포함해 30만 점을 소장하고 있으며, 루이스 칸이 설계한 본관은 모더니즘 건축의 이정표로 꼽힙니다. 대학 미술관답게 모든 관람이 무료입니다.' where name = 'YALE UNIVERSITY ART GALLERY';
update gallery_exhibitions set intro = '1870년 뉴욕 시민들이 설립한 메트로폴리탄 미술관은 5,000년 인류 예술사를 아우르는 200만 점 이상의 컬렉션을 소장한, 서반구 최대의 미술관입니다. 이집트 덴두르 신전부터 렘브란트, 페르메이르, 그리고 고흐·모네·드가의 인상주의 걸작까지 인류 문명의 정수가 센트럴파크 곁 한 건물 안에 모여 있습니다. 본 전시는 유럽 회화관의 명작들을 중심으로 한 컬렉션 하이라이트입니다.' where name = '메트로폴리탄';
update gallery_exhibitions set intro = '오슬로의 뭉크미술관(MUNCH)은 에드바르 뭉크가 1944년 세상을 떠나며 오슬로시에 유증한 회화 1,100여 점과 판화 18,000여 점 등 방대한 유산을 소장한, 한 작가를 위한 세계 최대 규모의 미술관입니다. 2021년 오슬로 항구에 13층 규모의 신축 건물로 이전하며 북유럽의 새로운 문화 랜드마크가 되었습니다. 「절규」의 회화·파스텔 버전을 비롯해 사랑과 불안, 죽음을 응시한 뭉크 예술의 전모를 만날 수 있습니다.' where name = '뭉크미술관';
update gallery_exhibitions set intro = '필라델피아의 반스 파운데이션은 의약품으로 부를 쌓은 앨버트 반스 박사가 수집한 인상주의·후기인상주의 컬렉션으로, 르누아르 181점, 세잔 69점, 마티스 59점이라는 세계에서 가장 밀도 높은 소장 목록을 자랑합니다. 반스 박사는 작품을 시대나 유파가 아닌 형태와 색채의 조화에 따라 벽면에 배치하는 독창적 ''앙상블'' 전시법을 고안했고, 이 배치는 오늘날까지 그대로 유지되고 있습니다. 쇠라의 「포즈를 취한 여인들」과 마티스의 「생의 기쁨」 같은 미술사의 이정표들이 이곳에 있습니다.' where name = '반스 미술관';
update gallery_exhibitions set intro = '스톡홀름의 스웨덴 국립미술관은 1792년 설립된 북유럽에서 가장 오래된 미술관 중 하나로, 왕실 컬렉션에서 출발한 70만 점의 소장품을 자랑합니다. 렘브란트의 「바타비아인의 음모」와 프랑스 로코코 회화의 알찬 컬렉션, 그리고 칼 라르손이 중앙 계단에 그린 대형 벽화로 유명합니다. 안데르스 소른, 칼 라르손 등 스웨덴 국민화가들의 대표작과 함께 북유럽 미술의 황금기를 조망할 수 있습니다.' where name = '스웨덴국립미술관';
update gallery_exhibitions set intro = '1948년 설립된 슬로바키아 국립 갤러리는 브라티슬라바 다뉴브 강변의 옛 병영 건물을 중심으로 한 슬로바키아 최대의 미술관 네트워크입니다. 고딕과 바로크 종교미술부터 19세기 풍경화, 20세기 슬로바키아 모더니즘까지 중부 유럽 미술의 독자적 흐름을 보여주며, 최근 대대적인 리노베이션으로 유럽에서 주목받는 현대적 전시 공간으로 재탄생했습니다. 본 전시는 슬로바키아와 중부 유럽 화가들의 서정적인 풍경화들을 소개합니다.' where name = '슬로바키아 국립 갤러리';
update gallery_exhibitions set intro = '1879년 설립된 시카고 미술관은 쇠라의 「그랑드 자트 섬의 일요일 오후」, 그랜트 우드의 「아메리칸 고딕」, 호퍼의 「나이트호크」라는 미국에서 가장 유명한 그림 세 점을 모두 소장한 곳입니다. 파리 밖에서 가장 뛰어난 인상주의 컬렉션으로 평가받으며, 모네의 「수련」과 「건초더미」 연작, 르누아르, 카유보트의 걸작들이 미시간 호숫가의 보자르 양식 본관을 채우고 있습니다. 밀레니엄 파크와 이어지는 현대관은 렌초 피아노의 설계입니다.' where name = '시카고미술관';
update gallery_exhibitions set intro = '네덜란드 암스테르담의 레이크스뮤지엄은 렘브란트의 「야경」을 위해 지어졌다 해도 과언이 아닌 네덜란드 국립미술관입니다. 페르메이르의 「우유 따르는 여인」, 프란스 할스, 얀 스테인 등 17세기 네덜란드 황금기 회화의 세계 최대 컬렉션을 소장하며, 페트뤼스 카위퍼르스가 설계한 1885년 네오고딕 건물은 10년간의 대개조를 거쳐 2013년 재개관했습니다. 미술관을 관통하는 자전거 통로는 암스테르담다운 명물입니다.' where name = '암스테르담 국립미술관';
update gallery_exhibitions set intro = '미국 코네티컷 뉴헤이븐의 예일 영국미술센터는 자선가 폴 멜런이 평생 수집한 영국 미술을 예일대학교에 기증하며 1977년 개관한, 영국 본토 밖에서 가장 방대한 영국 미술 컬렉션입니다. 터너와 컨스터블의 풍경화, 스터브스의 동물화, 호가스와 게인즈버러의 초상화 등 5세기에 걸친 영국 회화사를 아우릅니다. 건축가 루이스 칸의 유작인 미술관 건물은 자연광을 다루는 방식으로 건축사에 남은 걸작입니다.' where name = '예일센터브리티시아트';
update gallery_exhibitions set intro = '1916년 개관한 클리블랜드 미술관은 ''모든 사람을 위해, 영원히(For the Benefit of All the People Forever)''라는 설립 정신에 따라 지금까지 무료 입장을 지켜온 미국의 대표 미술관입니다. 카라바조, 터너, 모네, 반 고흐를 아우르는 유럽 회화와 세계적 수준의 아시아·이집트 컬렉션 등 6만 점 이상을 소장하며, 특히 중세 유럽 보물과 인상주의 컬렉션의 질은 미국 최고 수준으로 평가받습니다.' where name = '클리블랜드 미술관';
update gallery_exhibitions set intro = '알베르트 에델펠트(1854-1905)는 핀란드 미술을 유럽 무대에 올린 국민화가입니다. 파리에서 활동하며 프랑스 자연주의의 세련된 기법으로 핀란드의 빛과 사람들을 그렸고, 1886년작 「파스퇴르의 초상」으로 레지옹 도뇌르 훈장을 받으며 국제적 명성을 얻었습니다. 핀란드 화가 최초로 루브르에 작품이 소장되었으며, 그의 성공은 갈렌칼렐라 등 후배 화가들이 핀란드 황금기를 여는 길을 닦았습니다. 여름 군도의 뱃놀이와 여인들을 그린 야외 풍경화들은 북유럽 인상주의의 백미로 꼽힙니다.' where name = 'Albert Edelfelt';
update gallery_exhibitions set intro = '알프레드 시슬레(1839-1899)는 영국 국적으로 평생 프랑스에서 활동한 인상주의 창립 멤버로, 모네·르누아르와 함께 글레르의 화실에서 수학했습니다. 동료들이 초상과 인물로 영역을 넓힐 때에도 오직 풍경만을 그린 가장 순수한 인상주의 풍경화가로 남았으며, 하늘의 표정을 담아내는 능력에서는 당대의 누구도 따를 수 없다는 평가를 받았습니다. 마를리항의 홍수 연작과 모레쉬르루앙의 사계는 그의 대표작입니다. 생전에는 인정받지 못했으나 사후 인상주의의 핵심으로 재평가되었습니다.' where name = 'Alfred Sisley';
update gallery_exhibitions set intro = '바렌트 코르넬리스 쿠쿠크(1803-1862)는 ''풍경화의 왕자''로 불린 네덜란드 낭만주의 풍경화의 일인자입니다. 17세기 네덜란드 황금기의 전통에 낭만주의적 숭고미를 결합해 장엄한 떡갈나무 숲, 겨울 운하, 석양의 시골길을 그렸고, 유럽 왕실들이 앞다투어 그의 작품을 수집했습니다. 독일 클레베에 정착해 자신의 아틀리에와 회화 아카데미를 세웠으며, 그의 화풍은 네덜란드와 독일 풍경화 세대 전체에 영향을 미쳤습니다.' where name = 'Barend Cornelis Koekkoek';
update gallery_exhibitions set intro = '칼 홀쇠에(1863-1935)는 고요한 실내 정경의 시인이라 불리는 덴마크 화가입니다. 절친 빌헬름 함메르쇠이와 함께 덴마크 실내화 전통을 이끌며, 창으로 스며드는 부드러운 빛과 등을 돌린 여인, 반질한 마호가니 가구가 있는 정적의 공간을 평생 탐구했습니다. 17세기 네덜란드 실내화의 유산을 세기말 북유럽의 감수성으로 되살린 그의 그림은 일상의 평온이 지닌 깊이를 보여줍니다.' where name = 'Carl Holsøe';
update gallery_exhibitions set intro = '칼 라르손(1853-1919)은 스웨덴인들이 가장 사랑하는 국민화가입니다. 스톡홀름 빈민가에서 태어나 파리에서 수채화가로 성공했고, 아내 카린과 순드보른 마을의 집 ''릴라 히트나스''를 꾸미며 그린 수채 연작 「우리 집」으로 불멸의 명성을 얻었습니다. 햇살 가득한 실내, 아이들의 일상, 소박한 축제를 담은 그의 그림은 오늘날 스칸디나비아 인테리어 미학의 원형이 되었으며, 스웨덴 국립미술관 계단홀의 대형 벽화도 그의 작품입니다.' where name = 'Carl Larsson';
update gallery_exhibitions set intro = '칼 라이헤르트(1836-1918)는 오스트리아 그라츠 출신의 동물화가로, 강아지와 고양이의 표정을 사랑스럽게 포착한 소품들로 유럽 전역에서 인기를 얻었습니다. 화가 집안에서 태어나 아버지에게 그림을 배웠고, 테리어와 닥스훈트 등 견종의 특징과 개성을 세밀하게 그려내 ''개 초상화가''라는 애칭을 얻었습니다. 그의 작품은 비더마이어 전통의 온기와 유머를 간직한 19세기 동물화의 대표적 사례입니다.' where name = 'Carl Reichert';
update gallery_exhibitions set intro = '찰스 커트니 커런(1861-1942)은 꽃과 여성, 여름 햇살을 서정적으로 그린 미국 인상주의 화가입니다. 파리 아카데미 쥘리앙에서 수학한 뒤 뉴욕주 크래그스무어 예술인 마을에 정착해, 산등성이 위 흰 드레스의 여인들과 만개한 정원을 담은 밝고 투명한 화면으로 사랑받았습니다. 미국 국립디자인아카데미 회원으로 활동하며 미국적 인상주의의 낙관적 아름다움을 대표했습니다.' where name = 'Charles Courtney Curran';
update gallery_exhibitions set intro = '대니얼 리지웨이 나이트(1839-1924)는 필라델피아 출신으로 프랑스에 정착해 농촌 여인들의 일상을 그린 화가입니다. 파리 에콜 데 보자르에서 수학하고 메소니에에게 배웠으며, 센 강변 롤부아즈 마을에 유리 아틀리에를 짓고 정원의 꽃과 강가에서 쉬는 시골 처녀들을 화폭에 담았습니다. 아카데미즘의 정교한 묘사와 인상주의적 야외 빛을 결합한 그의 화면은 프랑스 정부가 레지옹 도뇌르로 인정한 목가적 아름다움의 전형입니다.' where name = 'Daniel Ridgway Knight';
update gallery_exhibitions set intro = '데이비드 제임스(1853-1904)는 파도만을 평생 그린 영국의 해양화가입니다. 콘월 해안에서 대서양의 큰 파도가 부서지는 순간을 관찰하며, 물보라의 투명함과 파도 속을 통과하는 빛을 놀랍도록 사실적으로 포착했습니다. 그의 롤러(대형 파도) 연작은 바다의 힘과 아름다움을 담은 빅토리아 시대 해양화의 백미로, 오늘날까지 파도 그림의 교과서로 불립니다.' where name = 'David James';
update gallery_exhibitions set intro = '외젠 갈리앙랄루(1854-1941)는 벨 에포크 파리의 거리를 기록한 프랑스 화가입니다. 구아슈와 수채로 오페라 대로의 마차 행렬, 눈 내린 개선문, 불 밝힌 극장가와 꽃시장을 그렸으며, 계약 문제를 피하기 위해 여러 가명으로 활동한 일화로도 유명합니다. 사진보다 생생하게 1900년 전후 파리의 공기를 전하는 그의 작은 화면들은 오늘날 그 시대를 그리워하는 이들에게 가장 사랑받는 이미지가 되었습니다.' where name = 'Eugène Galien-Laloue';
update gallery_exhibitions set intro = '프레데리크 우브롱(1851-1908)은 19세기 말 파리의 일상을 독특한 질감으로 담아낸 프랑스 화가입니다. 유화와 데트랑프를 혼합한 실험적 기법으로 거리의 군중, 공원의 산책자, 안개 낀 센 강변을 스케치하듯 빠르게 포착했으며, 파리시가 그의 작품 다수를 사들여 카르나발레 박물관에 소장했습니다. 인상주의와 후기인상주의 사이에서 도시의 순간을 기록한 개성적인 목격자였습니다.' where name = 'Frédéric Houbron';
update gallery_exhibitions set intro = '프레데리크 술라크루아(1858-1933)는 로마에서 태어나 피렌체에서 활동한 프랑스계 화가로, 로코코 리바이벌 살롱 회화의 대가입니다. 18세기풍 드레스를 입은 귀부인과 신사의 우아한 구애 장면을 주로 그렸으며, 비단과 새틴, 레이스의 질감을 극사실로 재현하는 솜씨는 당대 유럽과 미국 컬렉터들을 매료시켰습니다. 화려한 세부와 로맨틱한 서사가 어우러진 그의 화면은 벨 에포크 취향의 정수를 보여줍니다.' where name = 'Frédéric Soulacroix';
update gallery_exhibitions set intro = '조반니 볼디니(1842-1931)는 이탈리아 페라라 출신으로 파리 사교계를 정복한 초상화의 거장입니다. 휘몰아치는 듯한 역동적 붓질로 백작부인과 여배우, 멋쟁이 신사들을 실제보다 더 우아하고 생동감 있게 그려 ''스와시버클링 스타일''이라는 별명을 얻었고, 사전트와 함께 벨 에포크 초상화의 양대 산맥으로 군림했습니다. 베르디의 초상과 「마르케사 카사티」 같은 대표작은 한 시대의 화려함을 응축한 아이콘입니다.' where name = 'Giovanni Boldini';
update gallery_exhibitions set intro = '구스타프 클림트(1862-1918)는 빈 분리파의 초대 회장으로서 아카데미즘에 반기를 들고 새로운 예술의 시대를 연 오스트리아의 거장입니다. 비잔틴 모자이크에서 영감을 받은 금박의 「키스」와 「아델레 블로흐바우어의 초상」으로 미술사상 가장 화려한 ''황금 시기''를 이룩했으며, 아터제 호수의 풍경화들에서는 반짝이는 모자이크적 화면으로 자연을 장식적 패턴으로 승화시켰습니다. 관능과 죽음, 생명의 순환을 응시한 그의 예술은 세기말 빈 문화의 정점입니다.' where name = 'Gustav Klimt';
update gallery_exhibitions set intro = '헨리크 시에미라츠키(1843-1902)는 고대 그리스·로마의 장대한 장면을 그린 폴란드 아카데미즘의 거장입니다. 로마에 아틀리에를 두고 활동하며 「네로의 횃불」 같은 대작으로 유럽 전역에 명성을 떨쳤고, 햇살 아래 대리석과 꽃, 지중해의 푸른 바다를 눈부시게 재현하는 솜씨로 ''태양의 화가''라 불렸습니다. 크라쿠프와 바르샤바 국립극장의 무대막을 그렸으며, 그의 대작들은 폴란드 국립박물관들의 자랑입니다.' where name = 'Henryk Siemiradzki';
update gallery_exhibitions set intro = '장 베로(1849-1935)는 벨 에포크 파리의 삶을 가장 충실하게 기록한 풍속화가입니다. 샹젤리제의 산책자들, 카페의 신사들, 몽마르트르의 재봉사 아가씨들을 사진처럼 정밀하면서도 따뜻한 시선으로 그렸으며, 마차 안에서 스케치하며 거리의 순간을 포착한 일화로 유명합니다. 그의 그림들은 프루스트가 문학으로 남긴 파리를 회화로 남긴 시대의 앨범입니다.' where name = 'Jean Béraud';
update gallery_exhibitions set intro = '옌스 유엘(1745-1802)은 18세기 덴마크 최고의 초상화가로, 덴마크 황금기 회화의 토대를 놓은 인물입니다. 왕실과 부르주아의 초상을 로코코의 우아함과 계몽주의적 자연스러움으로 그렸고, 코펜하겐 왕립미술아카데미 교수로서 훗날 황금기를 이끌 에케르스베르 세대를 길러냈습니다. 덴마크 회화에서 풍경을 배경으로 한 초상의 전통을 연 선구자이기도 합니다.' where name = 'Jens Juel';
update gallery_exhibitions set intro = '존 앳킨슨 그림쇼(1836-1893)는 달빛 젖은 밤거리를 그린 빅토리아 시대 영국의 야경 화가입니다. 리즈의 철도 사무원에서 독학으로 화가가 되어, 가스등이 반짝이는 항구의 부두, 비에 젖은 골목, 낙엽 진 교외의 달밤을 신비로운 정밀함으로 담았습니다. 휘슬러가 ''나는 그림쇼의 달밤 그림을 보기 전까지 내가 야경의 발명자라 생각했다''고 고백했을 만큼, 그는 밤의 정서를 그리는 데 있어 독보적 존재였습니다.' where name = 'John Atkinson Grimshaw';
update gallery_exhibitions set intro = '존 싱어 사전트(1856-1925)는 이탈리아에서 태어난 미국인으로, 에드워드 시대 상류사회의 초상을 그린 당대 최고의 초상화가입니다. 파리 살롱을 뒤흔든 「마담 X」 스캔들 이후 런던으로 옮겨 명사들의 초상을 독점하다시피 했으며, 벨라스케스에게 배운 유려한 붓질은 ''한 번의 스트로크로 살아있는 피부를 만든다''는 찬사를 받았습니다. 말년에는 초상을 떠나 알프스와 베네치아의 수채화, 보스턴 도서관 벽화에 몰두하며 또 다른 경지를 열었습니다.' where name = 'John Singer Sargent';
update gallery_exhibitions set intro = '요제프 라우어(1818-1881)는 빈 비더마이어 시대의 꽃 정물화가입니다. 빈 미술아카데미에서 수학하고 장미, 작약, 과일과 새 둥지가 어우러진 화면을 보석세공처럼 정밀하게 그렸으며, 꽃잎의 이슬과 곤충까지 담아내는 세부 묘사로 사랑받았습니다. 그의 정물화는 산업화 이전 빈 부르주아 가정의 소박한 풍요와 자연 애호를 증언하는 시대의 기록이기도 합니다.' where name = 'Josef Lauer';
update gallery_exhibitions set intro = '줄리어스 르블랑 스튜어트(1855-1919)는 필라델피아 설탕 재벌의 아들로 파리에서 나고 자라며 사교계의 안쪽에서 그 화려함을 그린 화가입니다. ''파리의 미국인''이라 불리며 요트 파티, 살롱의 무도회, 숲속의 피크닉 등 상류사회의 여가를 대형 화면에 담았고, 제롬과 마드라조에게 배운 정교한 기법으로 드레스와 샴페인 잔의 광택까지 재현했습니다. 사전트가 초상으로 남긴 시대를 그는 파티 장면으로 남겼습니다.' where name = 'Julius Leblanc Stewart';
update gallery_exhibitions set intro = '라우리츠 아네르센 링(1854-1933)은 덴마크 사실주의와 상징주의를 잇는 화가로, 20세기 덴마크 미술의 아버지로 불립니다. 가난한 농촌 출신으로 자신이 자란 시골 마을의 이름 ''링''을 성으로 삼았고, 밭일하는 농부, 기차를 기다리는 사람들, 문가에 선 아내의 모습을 통해 근대화의 문턱에 선 덴마크의 삶을 성찰적으로 그렸습니다. 정적과 상념이 흐르는 그의 화면은 함메르쇠이와는 또 다른 덴마크적 고요의 얼굴입니다.' where name = 'L.A. Ring';
update gallery_exhibitions set intro = '마스든 하틀리(1877-1943)는 미국 모더니즘의 개척자로, 유럽 아방가르드를 미국적 감수성으로 소화한 화가이자 시인입니다. 1차 대전 전 베를린에서 그린 군사적 상징의 추상 연작으로 유럽 모더니즘의 한복판에 섰고, 말년에는 고향 메인주로 돌아와 어부들과 카타딘 산을 두껍고 대담한 색면으로 그리며 ''메인의 화가''로 자리매김했습니다. 그의 여정은 미국 미술이 지역성과 모더니즘을 화해시키는 과정 그 자체였습니다.' where name = 'Marsden Hartley';
update gallery_exhibitions set intro = '피에르오귀스트 르누아르(1841-1919)는 삶의 기쁨을 그린 인상주의의 대표 화가입니다. 리모주의 가난한 재단사 집안에서 태어나 도자기 공방 견습공으로 출발했으며, 「물랭 드 라 갈레트의 무도회」와 「뱃놀이 일행의 오찬」에서 햇살 아래 어울리는 파리 서민들의 행복을 영원히 붙잡았습니다. 말년에는 심한 류머티즘으로 붓을 손에 묶고도 그림을 멈추지 않았고, 진주빛 살결의 누드 연작으로 고전과 인상주의를 화해시켰습니다. ''그림은 즐겁고 유쾌하고 예쁜 것이어야 한다''는 그의 신념은 화폭마다 살아 있습니다.' where name = 'Pierre-Auguste Renoir';
update gallery_exhibitions set intro = '산티아고 루시뇰(1861-1931)은 카탈루냐 모데르니스메 운동을 이끈 화가이자 작가입니다. 바르셀로나 섬유 부호의 아들로 태어나 예술을 위해 가업을 등졌고, 파리 몽마르트르에서 보헤미안으로 살며 시체스에 예술가들의 성지 ''카우 페라트''를 세웠습니다. 그라나다와 아란후에스의 버려진 정원들을 그린 정원 연작은 시들어가는 아름다움에 대한 세기말적 명상으로, 젊은 피카소에게도 깊은 영향을 미쳤습니다.' where name = 'Santiago Rusiñol';
update gallery_exhibitions set intro = '존 래버리 경(1856-1941)은 벨파스트 출신으로 글래스고 보이즈의 일원으로 출발해 에드워드 시대 최고 초상화가의 반열에 오른 아일랜드 화가입니다. 파리에서 자연주의를 배워 야외의 빛을 우아하게 다뤘고, 윈스턴 처칠에게 그림을 가르쳤으며, 아내 헤이즐의 초상은 아일랜드 지폐에 실렸습니다. 테니스 코트와 요트, 온실의 오후 등 근대적 여가의 장면들을 세련된 색조로 남겼습니다.' where name = 'Sir John Lavery';
update gallery_exhibitions set intro = '토머스 모런(1837-1926)은 미국 서부의 장엄함을 유럽과 동부에 알린 허드슨강파의 마지막 거장입니다. 1871년 옐로스톤 탐사대에 동행해 그린 수채화들은 의회가 옐로스톤을 세계 최초의 국립공원으로 지정하는 데 결정적 역할을 했고, 그의 대작 「옐로스톤 그랜드캐니언」은 의회의사당에 걸렸습니다. 터너에게 배운 빛과 색의 드라마로 그랜드캐니언, 그린리버의 절벽을 신화적 풍경으로 승화시켰습니다.' where name = 'Thomas Moran';
update gallery_exhibitions set intro = '티나 블라우(1845-1916)는 오스트리아 분위기 인상주의를 대표하는 빈의 여성 풍경화가입니다. 여성의 미술 교육이 막혀 있던 시대에 프라터 공원의 봄 햇살을 그린 대작으로 파리 살롱에서 명예상을 받았고, 빈 여성미술학교를 공동 설립해 후진을 양성했습니다. 나뭇잎 사이로 부서지는 빛과 대기의 떨림을 담은 그녀의 화면은 빈 인상주의의 가장 신선한 성취로 재평가받고 있습니다.' where name = 'Tina Blau';
update gallery_exhibitions set intro = '빈센트 반 고흐(1853-1890)는 단 10년의 화가 인생 동안 900점의 유화를 남기며 미술사를 바꾼 네덜란드의 화가입니다. 목사의 아들로 태어나 화상, 교사, 전도사를 거쳐 스물일곱에 그림을 시작했고, 아를의 태양 아래에서 「해바라기」와 「밤의 카페테라스」를, 생레미 요양원에서 「별이 빛나는 밤」과 「아이리스」를 그렸습니다. 소용돌이치는 붓질과 타오르는 색채는 눈에 보이는 세계 너머의 감정을 그리려 한 투쟁의 기록이며, 생전 단 한 점밖에 팔지 못했던 그의 그림은 오늘날 인류가 가장 사랑하는 예술이 되었습니다.' where name = 'Vincent van Gogh';
update gallery_exhibitions set intro = '에두아르 마네(1832-1883)는 근대 회화의 문을 연 프랑스의 화가입니다. 「풀밭 위의 점심식사」와 「올랭피아」로 살롱을 발칵 뒤집으며 회화가 신화가 아닌 동시대의 삶을 그려야 함을 선언했고, 카페 게르부아에 모여든 젊은 화가들의 정신적 지주로서 인상주의 탄생의 산파가 되었습니다. 정작 자신은 인상주의전에 한 번도 참여하지 않고 살롱에서의 인정을 추구한 독립적 혁명가였으며, 벨라스케스풍의 검은색을 구사한 마지막 거장이자 빛의 회화의 첫 거장이었습니다.' where name = 'Édouard Manet';
update gallery_exhibitions set intro = '이인성(1912-1950)은 ''조선의 천재 화가''로 불린 한국 근대 서양화의 대표 작가입니다. 대구의 가난한 집안에서 태어나 독학에 가깝게 그림을 시작했고, 조선미술전람회에서 최연소 특선을 거듭하며 신화가 되었습니다. 「경주의 산곡에서」와 「가을 어느 날」에서 붉은 흙과 강렬한 태양 아래 조선의 향토색을 인상주의적 감각으로 담아냈으며, 수채화에서도 당대 최고의 기량을 보였습니다. 서른여덟의 나이에 비극적으로 생을 마감했지만, 그의 화면에 담긴 조선의 빛과 색은 한국 근대미술의 원형으로 남아 있습니다.' where name = '이인성';
update gallery_exhibitions set intro = '이중섭(1916-1956)은 소 그림으로 한국인의 혼을 그린 국민화가입니다. 평안남도 부유한 집안에서 태어나 일본에서 모더니즘을 수학했고, 전쟁의 피난길에서 가족과 생이별한 뒤 제주와 부산, 통영을 떠돌며 그림에 모든 것을 쏟았습니다. 담뱃갑 은지에 못으로 새긴 은지화, 힘줄이 꿈틀대는 「흰 소」, 게와 물고기와 아이들이 뒤엉킨 가족 그림들은 궁핍 속에서도 꺼지지 않은 예술혼과 가족에 대한 사무치는 그리움의 기록입니다. 마흔에 요절한 그의 삶과 예술은 한국 근대미술의 가장 뜨거운 신화가 되었습니다.' where name = '이중섭';